function read(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v??fallback}catch{return fallback}}
function write(key,v){localStorage.setItem(key,JSON.stringify(v))}
function migrateLegacyData(){
  if(!localStorage.getItem(KEYS.branches)&&localStorage.getItem('pf_departments')){localStorage.setItem(KEYS.branches,localStorage.getItem('pf_departments'));localStorage.removeItem('pf_departments')}
  const stored=read(KEYS.employees,[]);
  if(stored.length){let changed=false;const normalized=stored.map(e=>{const n={...e};if(!n.branchId&&n.departmentId){n.branchId=n.departmentId;changed=true}for(const [k,v] of Object.entries({bank:'',accountNumber:'',emergencyPhone:'',salary:0})){if(!(k in n)){n[k]=v;changed=true}}delete n.departmentId;return n});if(changed)write(KEYS.employees,normalized)}
  if(!localStorage.getItem(KEYS.users)){
    const legacy=read(KEYS.legacyAccount,null);const users=DEFAULT_USERS.map(x=>({...x}));
    if(legacy?.username){users[0].username=legacy.username;users[0].password=legacy.password||'admin123'}
    write(KEYS.users,users);
  }
}
function seed(){migrateLegacyData();if(!localStorage.getItem(KEYS.branches))write(KEYS.branches,DEFAULT_BRANCHES);if(!localStorage.getItem(KEYS.employees))write(KEYS.employees,DEFAULT_EMPLOYEES);if(!localStorage.getItem(KEYS.attendance)){const t=todayISO(),sample={};DEFAULT_EMPLOYEES.forEach((e,i)=>sample[e.id]={status:i===4?'late':'present',time:i===4?'08:17':'07:55',note:''});write(KEYS.attendance,{[t]:sample})}if(!localStorage.getItem(KEYS.leaves))write(KEYS.leaves,[]);if(!localStorage.getItem(KEYS.interviews))write(KEYS.interviews,DEFAULT_INTERVIEWS);if(!localStorage.getItem(KEYS.evaluations))write(KEYS.evaluations,DEFAULT_EVALUATIONS);if(!localStorage.getItem(KEYS.settings))write(KEYS.settings,DEFAULT_SETTINGS);if(!localStorage.getItem(KEYS.users))write(KEYS.users,DEFAULT_USERS)}
let employees=[],branches=[],attendance={},leaves=[],interviews=[],evaluations=[],settings={},users=[],currentUser=null,activeBranchId='all';
function load(){employees=read(KEYS.employees,[]).map(e=>({...e,bank:e.bank||'',accountNumber:e.accountNumber||'',emergencyPhone:e.emergencyPhone||'',salary:Number(e.salary)||0}));branches=read(KEYS.branches,[]);attendance=read(KEYS.attendance,{});leaves=read(KEYS.leaves,[]);interviews=read(KEYS.interviews,[]).map(i=>({...i,score:i.score===''||i.score==null?null:Number(i.score)}));evaluations=read(KEYS.evaluations,[]).map(v=>({...v,performance:Number(v.performance)||0,discipline:Number(v.discipline)||0,attendance:Number(v.attendance)||0,teamwork:Number(v.teamwork)||0,initiative:Number(v.initiative)||0,status:v.status==='draft'?'draft':'published'}));settings={...DEFAULT_SETTINGS,...read(KEYS.settings,{})};users=read(KEYS.users,DEFAULT_USERS).map(u=>({...u,accessRole:ACCESS[u.accessRole]?u.accessRole:'employee',employeeId:u.employeeId||''}));const sid=sessionStorage.getItem(SESSION_KEY);currentUser=users.find(u=>u.id===sid)||null;activeBranchId=resolveBranchContext()}
function saveAll(){write(KEYS.employees,employees);write(KEYS.branches,branches);write(KEYS.attendance,attendance);write(KEYS.leaves,leaves);write(KEYS.interviews,interviews);write(KEYS.evaluations,evaluations);write(KEYS.settings,settings);write(KEYS.users,users)}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function initials(name=''){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'--'}
function branchName(id){return branches.find(d=>d.id===id)?.name||'Tanpa Cabang'}
function fmtCurrency(v){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(v)||0)}
function fmtDate(v){if(!v)return'—';const [y,m,d]=v.split('-').map(Number);return new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(y,m-1,d))}
function daysBetween(a,b){return Math.max(1,Math.round((new Date(b+'T00:00:00')-new Date(a+'T00:00:00'))/86400000)+1)}
function toast(msg,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;$('#toastStack').appendChild(el);setTimeout(()=>el.remove(),2800)}
function roleLabel(role=currentUser?.accessRole){return ROLE_LABELS[role]||'Pengguna'}
function access(){return ACCESS[currentUser?.accessRole]||ACCESS.employee}
function can(key){return !!access()[key]}
function linkedEmployee(user=currentUser){return employees.find(e=>e.id===user?.employeeId)||null}
function userBranchId(user=currentUser){return linkedEmployee(user)?.branchId||''}
function branchContextKey(user=currentUser){return `${BRANCH_CONTEXT_PREFIX}${user?.id||'guest'}`}
function resolveBranchContext(){if(!currentUser)return'all';const a=access();if(a.scope!=='all')return userBranchId()||'all';const stored=sessionStorage.getItem(branchContextKey());return stored==='all'||branches.some(b=>b.id===stored)?stored:'all'}
function setBranchContext(id){if(!currentUser)return;activeBranchId=access().scope==='all'&&(id==='all'||branches.some(b=>b.id===id))?id:(userBranchId()||'all');if(access().scope==='all')sessionStorage.setItem(branchContextKey(),activeBranchId)}
function activeBranch(){return activeBranchId==='all'?null:branches.find(b=>b.id===activeBranchId)||null}
function scopedEmployees(){const a=access();if(a.scope==='self')return employees.filter(e=>e.id===currentUser?.employeeId);if(a.scope==='branch'){const bid=userBranchId();return employees.filter(e=>e.branchId===bid)}return activeBranchId==='all'?employees:employees.filter(e=>e.branchId===activeBranchId)}
function scopedEmployeeIds(){return new Set(scopedEmployees().map(e=>e.id))}
function scopedLeaves(){const ids=scopedEmployeeIds();return leaves.filter(l=>ids.has(l.employeeId))}
function scopedInterviews(){const a=access();if(a.scope==='branch'){const bid=userBranchId();return interviews.filter(i=>i.branchId===bid)}if(a.scope==='self')return[];return activeBranchId==='all'?interviews:interviews.filter(i=>i.branchId===activeBranchId)}
function scopedEvaluations(){const ids=scopedEmployeeIds();return evaluations.filter(v=>ids.has(v.employeeId)&&(access().scope!=='self'||v.status==='published'))}
function scopedBranches(){if(access().scope==='all')return activeBranchId==='all'?branches:branches.filter(b=>b.id===activeBranchId);const bid=userBranchId();return branches.filter(b=>b.id===bid)}
function viewAllowed(view){return !!currentUser&&access().views.includes(view)}
function requirePermission(key,msg='Anda tidak memiliki hak untuk tindakan ini.'){if(!can(key)){toast(msg,'error');return false}return true}
let activeCustomSelect=null;
function closeCustomSelect(){if(!activeCustomSelect)return;activeCustomSelect.trigger.setAttribute('aria-expanded','false');activeCustomSelect.shell.classList.remove('open');activeCustomSelect.menu.remove();activeCustomSelect=null}
function syncCustomSelect(select){const shell=select.closest('.custom-select'),trigger=shell?.querySelector('.custom-select-trigger'),label=trigger?.querySelector('.custom-select-value');if(!shell||!trigger||!label)return;const selected=select.options[select.selectedIndex];label.textContent=selected?.textContent||'Pilih opsi';trigger.disabled=select.disabled;trigger.classList.toggle('is-placeholder',!select.value)}
function positionCustomSelectMenu(){if(!activeCustomSelect)return;const {trigger,menu}=activeCustomSelect,rect=trigger.getBoundingClientRect(),gap=7,margin=8,width=Math.max(rect.width,180);menu.style.width=`${width}px`;menu.style.left=`${Math.max(margin,Math.min(rect.left,window.innerWidth-width-margin))}px`;menu.style.maxHeight=`${Math.min(290,window.innerHeight-24)}px`;const estimated=Math.min(290,Math.max(70,menu.scrollHeight)),below=window.innerHeight-rect.bottom-gap,above=rect.top-gap;menu.style.top=below>=Math.min(estimated,190)||below>=above?`${Math.min(window.innerHeight-estimated-margin,rect.bottom+gap)}px`:`${Math.max(margin,rect.top-estimated-gap)}px`}
function openCustomSelect(select,trigger,shell){if(select.disabled)return;closeCustomDatePicker();if(activeCustomSelect?.select===select){closeCustomSelect();return}closeCustomSelect();const menu=document.createElement('div');menu.className='custom-select-menu';menu.setAttribute('role','listbox');[...select.options].forEach((option,index)=>{const item=document.createElement('button');item.type='button';item.className='custom-select-option'+(option.selected?' selected':'');item.disabled=option.disabled;item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.selected));item.innerHTML=`<span>${esc(option.textContent)}</span>${option.selected?'<i>✓</i>':''}`;item.onclick=()=>{select.selectedIndex=index;select.dispatchEvent(new Event('change',{bubbles:true}));syncCustomSelect(select);closeCustomSelect()};menu.appendChild(item)});document.body.appendChild(menu);activeCustomSelect={select,trigger,shell,menu};shell.classList.add('open');trigger.setAttribute('aria-expanded','true');positionCustomSelectMenu()}
function enhanceSelect(select){if(select.dataset.customSelect==='1'){syncCustomSelect(select);return}select.dataset.customSelect='1';const shell=document.createElement('div');shell.className='custom-select'+(select.classList.contains('attendance-select')?' custom-select--attendance':'');select.parentNode.insertBefore(shell,select);shell.appendChild(select);select.classList.add('native-select-hidden');const trigger=document.createElement('button');trigger.type='button';trigger.className='custom-select-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.innerHTML='<span class="custom-select-value"></span><span class="custom-select-arrow" aria-hidden="true"></span>';shell.appendChild(trigger);syncCustomSelect(select);trigger.onclick=e=>{e.stopPropagation();openCustomSelect(select,trigger,shell)};trigger.onkeydown=e=>{if(['Enter',' ','ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();openCustomSelect(select,trigger,shell)}else if(e.key==='Escape')closeCustomSelect()};select.addEventListener('change',()=>syncCustomSelect(select));new MutationObserver(()=>syncCustomSelect(select)).observe(select,{childList:true,subtree:true,attributes:true})}
function enhanceSelects(root=document){root.querySelectorAll('select').forEach(enhanceSelect)}
document.addEventListener('click',e=>{if(activeCustomSelect&&!activeCustomSelect.shell.contains(e.target)&&!activeCustomSelect.menu.contains(e.target))closeCustomSelect()});window.addEventListener('resize',closeCustomSelect);document.addEventListener('scroll',e=>{if(activeCustomSelect&&e.target!==activeCustomSelect.menu)closeCustomSelect()},true);

