function evaluationScore(v){const values=[v.performance,v.discipline,v.attendance,v.teamwork,v.initiative].map(x=>Math.max(0,Math.min(100,Number(x)||0)));return Math.round(values.reduce((a,b)=>a+b,0)/values.length)}
function evaluationGrade(score){return score>=90?'Istimewa':score>=80?'Sangat Baik':score>=70?'Baik':score>=60?'Cukup':'Perlu Perbaikan'}
function evaluationGradeClass(score){return score>=90?'excellent':score>=80?'very-good':score>=70?'good':score>=60?'fair':'attention'}
function evaluationStatusLabel(status){return status==='draft'?'Draft':'Final'}
function renderEvaluationOptions(){const employeeSelect=$('#evaluationEmployee'),branchFilter=$('#evaluationBranchFilter');if(!employeeSelect||!branchFilter)return;const allowed=scopedEmployees().filter(e=>e.status==='active');const selected=employeeSelect.value;employeeSelect.innerHTML=allowed.map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(e.code)} · ${esc(branchName(e.branchId))}</option>`).join('');if(allowed.some(e=>e.id===selected))employeeSelect.value=selected;const bs=scopedBranches(),cur=branchFilter.value||'all';branchFilter.innerHTML='<option value="all">Semua dalam cakupan</option>'+bs.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('');branchFilter.value=[...bs.map(b=>b.id),'all'].includes(cur)?cur:'all';const fixed=access().scope!=='all'||activeBranchId!=='all';if(fixed){branchFilter.value='all';branchFilter.disabled=true}else branchFilter.disabled=false;enhanceSelects();syncAllCustomSelects()}
function updateEvaluationPreview(){const ids=['evaluationPerformance','evaluationDiscipline','evaluationAttendance','evaluationTeamwork','evaluationInitiative'],values=ids.map(id=>Math.max(0,Math.min(100,Number($('#'+id)?.value)||0))),score=Math.round(values.reduce((a,b)=>a+b,0)/values.length);if($('#evaluationScorePreview'))$('#evaluationScorePreview').textContent=score;if($('#evaluationGradePreview'))$('#evaluationGradePreview').textContent=evaluationGrade(score)}
function renderEvaluations(){if(!viewAllowed('evaluation'))return;renderEvaluationOptions();const q=$('#evaluationSearch').value.trim().toLowerCase(),branch=$('#evaluationBranchFilter').value,period=$('#evaluationPeriodFilter').value,status=$('#evaluationStatusFilter').value;const rows=scopedEvaluations().filter(v=>{const e=employees.find(x=>x.id===v.employeeId);if(!e)return false;const searchable=[e.name,e.code,e.role,branchName(e.branchId),v.evaluatorName,v.notes,evaluationGrade(evaluationScore(v))];return(!q||searchable.some(x=>String(x||'').toLowerCase().includes(q)))&&(branch==='all'||e.branchId===branch)&&(!period||v.period===period)&&(status==='all'||v.status===status)}).sort((a,b)=>(b.period||'').localeCompare(a.period||'')||b.createdAt-a.createdAt);$('#evaluationTableBody').innerHTML=rows.map(v=>{const e=employees.find(x=>x.id===v.employeeId),score=evaluationScore(v),grade=evaluationGrade(score);return `<tr><td><div class="person-cell"><span class="employee-avatar">${initials(e?.name||'?')}</span><div><strong>${esc(e?.name||'Karyawan dihapus')}</strong><small>${esc(e?.code||'—')}</small></div></div></td><td><div class="stacked-cell"><strong>${esc(branchName(e?.branchId))}</strong><small>${esc(e?.role||'—')}</small></div></td><td><div class="stacked-cell"><strong>${esc(v.period||'—')}</strong><small>Oleh ${esc(v.evaluatorName||'—')}</small></div></td><td><div class="evaluation-score-cell"><strong>${score}</strong><span class="evaluation-grade ${evaluationGradeClass(score)}">${esc(grade)}</span></div></td><td><div class="stacked-cell evaluation-notes" title="${esc(v.notes||'')}"><strong>${esc(v.notes||'Belum ada catatan')}</strong><small>Kinerja ${Number(v.performance)||0} · Disiplin ${Number(v.discipline)||0} · Hadir ${Number(v.attendance)||0}</small></div></td><td><span class="status-badge evaluation-${esc(v.status)}">${evaluationStatusLabel(v.status)}</span></td><td>${can('evaluationManage')?`<div class="table-actions"><button class="icon-btn" data-edit-evaluation="${esc(v.id)}" title="Edit penilaian"><span data-icon="edit"></span></button><button class="icon-btn danger" data-delete-evaluation="${esc(v.id)}" title="Hapus penilaian"><span data-icon="trash"></span></button></div>`:''}</td></tr>`}).join('');$('#evaluationEmpty').classList.toggle('hidden',rows.length>0);const all=scopedEvaluations(),scores=all.map(evaluationScore);$('#evaluationTotal').textContent=all.length;$('#evaluationAverage').textContent=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):0;$('#evaluationExcellent').textContent=scores.filter(s=>s>=80).length;$('#evaluationAttention').textContent=scores.filter(s=>s<70).length;applyIcons($('#evaluationTableBody'));$$('[data-edit-evaluation]').forEach(b=>b.onclick=()=>openEvaluation(b.dataset.editEvaluation));$$('[data-delete-evaluation]').forEach(b=>b.onclick=()=>deleteEvaluation(b.dataset.deleteEvaluation))}
function openEvaluation(id=''){if(!requirePermission('evaluationManage','Role Anda hanya dapat melihat penilaian yang tersedia.'))return;const item=scopedEvaluations().find(x=>x.id===id);if(id&&!item){toast('Penilaian di luar cakupan akses Anda.','error');return}renderEvaluationOptions();$('#evaluationModalTitle').textContent=item?'Edit Penilaian':'Tambah Penilaian';$('#evaluationId').value=item?.id||'';$('#evaluationEmployee').value=item?.employeeId||scopedEmployees().find(e=>e.status==='active')?.id||'';$('#evaluationPeriod').value=item?.period||todayISO().slice(0,7);$('#evaluationStatus').value=item?.status||'draft';$('#evaluationPerformance').value=item?.performance??80;$('#evaluationDiscipline').value=item?.discipline??80;$('#evaluationAttendance').value=item?.attendance??80;$('#evaluationTeamwork').value=item?.teamwork??80;$('#evaluationInitiative').value=item?.initiative??80;$('#evaluationNotes').value=item?.notes||'';updateEvaluationPreview();syncAllCustomSelects();openModal('evaluationModal')}
