function renderBranches(){const bs=access().scope==='all'?branches:scopedBranches();$('#branchGrid').innerHTML=bs.map(d=>{const count=(access().scope==='all'?employees:scopedEmployees()).filter(e=>e.branchId===d.id).length;return `<article class="branch-card"><div class="branch-card-head"><span class="branch-card-icon"><span data-icon="building"></span></span>${can('branchManage')?`<div class="table-actions"><button class="icon-btn" data-edit-branch="${esc(d.id)}"><span data-icon="edit"></span></button><button class="icon-btn danger" data-delete-branch="${esc(d.id)}"><span data-icon="trash"></span></button></div>`:''}</div><h3>${esc(d.name)}</h3><p>${esc(d.description||'Belum ada deskripsi cabang.')}</p><div class="branch-meta"><span><small>Karyawan</small><br><strong>${count} orang</strong></span><span><small>Penanggung jawab</small><br><strong>${esc(d.head||'—')}</strong></span></div></article>`}).join('')||'<div class="empty-state"><h3>Belum ada cabang</h3><p>Belum ada cabang dalam cakupan Anda.</p></div>';applyIcons($('#branchGrid'));$$('[data-edit-branch]').forEach(b=>b.onclick=()=>openBranch(b.dataset.editBranch));$$('[data-delete-branch]').forEach(b=>b.onclick=()=>deleteBranch(b.dataset.deleteBranch));renderBranchOptions()}
function openBranch(id=''){if(!requirePermission('branchManage','Hanya Team IT dan Owner yang dapat mengubah cabang.'))return;const d=branches.find(x=>x.id===id);$('#branchModalTitle').textContent=d?'Edit Cabang':'Tambah Cabang';$('#branchId').value=d?.id||'';$('#branchName').value=d?.name||'';$('#branchHead').value=d?.head||'';$('#branchDescription').value=d?.description||'';openModal('branchModal')}
function deleteBranch(id){if(!requirePermission('branchManage','Anda tidak memiliki hak menghapus cabang.'))return;const d=branches.find(x=>x.id===id),count=employees.filter(e=>e.branchId===id).length,interviewCount=interviews.filter(i=>i.branchId===id).length;if(!d)return;if(count){toast(`Tidak dapat dihapus: masih ada ${count} karyawan`,'error');return}if(interviewCount){toast(`Tidak dapat dihapus: masih ada ${interviewCount} data interview`,'error');return}if(confirm(`Hapus cabang ${d.name}?`)){branches=branches.filter(x=>x.id!==id);write(KEYS.branches,branches);if(activeBranchId===id)setBranchContext('all');renderAll();toast('Cabang dihapus')}}
function attendanceRate30(){const ids=new Set(scopedEmployees().filter(e=>e.status==='active').map(e=>e.id));let scheduled=0,present=0;Object.entries(attendance).forEach(([date,day])=>{if((Date.now()-new Date(date+'T00:00:00'))/86400000<=30){Object.entries(day).forEach(([id,a])=>{if(ids.has(id)){scheduled++;if(['present','late'].includes(a.status))present++}})}});return scheduled?Math.round(present/scheduled*100):0}
function averageTenureMonths(){const active=scopedEmployees().filter(e=>e.status==='active'&&e.joinDate);if(!active.length)return 0;return Math.round(active.reduce((sum,e)=>sum+Math.max(0,(Date.now()-new Date(e.joinDate+'T00:00:00'))/(86400000*30.44)),0)/active.length)}
function renderReports(){const pool=scopedEmployees(),active=pool.filter(e=>e.status==='active').length,dataLeaves=scopedLeaves();$('#reportActive').textContent=active;$('#reportAttendance').textContent=`${attendanceRate30()}%`;$('#reportLeaves').textContent=dataLeaves.length;$('#reportTenure').textContent=`${averageTenureMonths()} bln`;renderBranchBars('#reportBranchBars');const inactive=pool.length-active;$('#statusDonut').innerHTML=`<div class="status-line"><i></i><span>Karyawan Aktif</span><strong>${active}</strong></div><div class="status-line"><i></i><span>Karyawan Nonaktif</span><strong>${inactive}</strong></div>`}
function exportCSV(){if(!requirePermission('export','Role Anda tidak memiliki hak export data.'))return;const headers=['Nama Lengkap','ID Karyawan','Cabang','Jabatan','Gaji','Status','Email','No. Telepon','Bank','No. Rekening','Tanggal Gabung','Jenis Kelamin','Alamat','No. Telepon Darurat'],rows=scopedEmployees().map(e=>[e.name,e.code,branchName(e.branchId),e.role,Number(e.salary)||0,e.status==='active'?'Aktif':'Nonaktif',e.email,e.phone,e.bank,e.accountNumber,e.joinDate,e.gender,e.address,e.emergencyPhone]),csv='\ufeff'+[headers,...rows].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`laporan-karyawan-${todayISO()}.csv`;a.click();URL.revokeObjectURL(url);toast('CSV karyawan berhasil dibuat')}
function renderUserOptions(){const select=$('#userEmployeeId'),current=select.value;select.innerHTML='<option value="">Tidak terhubung</option>'+employees.map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(e.code)} · ${esc(branchName(e.branchId))}</option>`).join('');select.value=employees.some(e=>e.id===current)?current:'';enhanceSelects()}
