  $('#accountSettingsForm').onsubmit=e=>{e.preventDefault();if(!currentUser)return;const u=$('#settingUsername').value.trim(),p=$('#settingPassword').value,c=$('#settingPasswordConfirm').value;if(users.some(x=>x.username.toLowerCase()===u.toLowerCase()&&x.id!==currentUser.id)){toast('Username sudah digunakan akun lain.','error');return}if(p&&p!==c){toast('Konfirmasi password tidak sama','error');return}currentUser.username=u;if(p)currentUser.password=p;write(KEYS.users,users);$('#settingPassword').value='';$('#settingPasswordConfirm').value='';toast('Akun login diperbarui')};
